-- Additive upgrade for an existing Beyond Rasooli Payload PostgreSQL schema.
-- No content rows or existing role assignments are changed.
DO $$ BEGIN
IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname='enum_site_settings_default_locale' AND typnamespace=current_schema()::regnamespace) THEN CREATE TYPE enum_site_settings_default_locale AS ENUM ('ps','fa','en'); END IF;
IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname='enum_site_settings_date_style' AND typnamespace=current_schema()::regnamespace) THEN CREATE TYPE enum_site_settings_date_style AS ENUM ('short','medium','long'); END IF;
IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname='enum_site_settings_numbering_system' AND typnamespace=current_schema()::regnamespace) THEN CREATE TYPE enum_site_settings_numbering_system AS ENUM ('latn','arabext','arab'); END IF;
END $$;
CREATE TABLE IF NOT EXISTS authors (id serial PRIMARY KEY, name varchar NOT NULL, image_id integer REFERENCES media(id) ON DELETE SET NULL, social_links_youtube varchar, social_links_instagram varchar, social_links_facebook varchar, social_links_x varchar, social_links_tiktok varchar, updated_at timestamp(3) with time zone NOT NULL DEFAULT now(), created_at timestamp(3) with time zone NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS authors_locales (bio varchar, id serial PRIMARY KEY, _locale _locales NOT NULL, _parent_id integer NOT NULL REFERENCES authors(id) ON DELETE CASCADE);
CREATE UNIQUE INDEX IF NOT EXISTS authors_locales_locale_parent_id_unique ON authors_locales(_locale,_parent_id);
CREATE TABLE IF NOT EXISTS glossary (id serial PRIMARY KEY, term_en varchar NOT NULL, term_ps varchar, term_fa varchar, do_not_translate boolean DEFAULT false, notes varchar, updated_at timestamp(3) with time zone NOT NULL DEFAULT now(), created_at timestamp(3) with time zone NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS glossary_term_en_idx ON glossary(term_en);
ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS default_locale enum_site_settings_default_locale DEFAULT 'ps' NOT NULL, ADD COLUMN IF NOT EXISTS publishing_timezone varchar DEFAULT 'Asia/Kabul' NOT NULL, ADD COLUMN IF NOT EXISTS date_style enum_site_settings_date_style DEFAULT 'medium', ADD COLUMN IF NOT EXISTS numbering_system enum_site_settings_numbering_system DEFAULT 'latn', ADD COLUMN IF NOT EXISTS default_o_g_image_id integer REFERENCES media(id) ON DELETE SET NULL;
ALTER TABLE site_settings_locales ADD COLUMN IF NOT EXISTS default_s_e_o_title varchar, ADD COLUMN IF NOT EXISTS default_s_e_o_description varchar;
ALTER TABLE articles ADD COLUMN IF NOT EXISTS cover_alt varchar, ADD COLUMN IF NOT EXISTS author_profile_id integer REFERENCES authors(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS og_image_id integer REFERENCES media(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS translated_at timestamp(3) with time zone, ADD COLUMN IF NOT EXISTS reviewed_at timestamp(3) with time zone, ADD COLUMN IF NOT EXISTS reviewed_by_id integer REFERENCES users(id) ON DELETE SET NULL;
ALTER TABLE _articles_v ADD COLUMN IF NOT EXISTS version_cover_alt varchar, ADD COLUMN IF NOT EXISTS version_author_profile_id integer REFERENCES authors(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS version_og_image_id integer REFERENCES media(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS version_translated_at timestamp(3) with time zone, ADD COLUMN IF NOT EXISTS version_reviewed_at timestamp(3) with time zone, ADD COLUMN IF NOT EXISTS version_reviewed_by_id integer REFERENCES users(id) ON DELETE SET NULL;
ALTER TABLE videos ADD COLUMN IF NOT EXISTS summary varchar, ADD COLUMN IF NOT EXISTS remote_poster_url varchar, ADD COLUMN IF NOT EXISTS og_image_id integer REFERENCES media(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS translated_at timestamp(3) with time zone, ADD COLUMN IF NOT EXISTS reviewed_at timestamp(3) with time zone, ADD COLUMN IF NOT EXISTS reviewed_by_id integer REFERENCES users(id) ON DELETE SET NULL;
ALTER TABLE _videos_v ADD COLUMN IF NOT EXISTS version_summary varchar, ADD COLUMN IF NOT EXISTS version_remote_poster_url varchar, ADD COLUMN IF NOT EXISTS version_og_image_id integer REFERENCES media(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS version_translated_at timestamp(3) with time zone, ADD COLUMN IF NOT EXISTS version_reviewed_at timestamp(3) with time zone, ADD COLUMN IF NOT EXISTS version_reviewed_by_id integer REFERENCES users(id) ON DELETE SET NULL;
ALTER TABLE payload_locked_documents_rels ADD COLUMN IF NOT EXISTS authors_id integer REFERENCES authors(id) ON DELETE CASCADE, ADD COLUMN IF NOT EXISTS glossary_id integer REFERENCES glossary(id) ON DELETE CASCADE;
CREATE INDEX IF NOT EXISTS authors_updated_at_idx ON authors(updated_at);
CREATE INDEX IF NOT EXISTS authors_created_at_idx ON authors(created_at);
CREATE INDEX IF NOT EXISTS glossary_updated_at_idx ON glossary(updated_at);
CREATE INDEX IF NOT EXISTS glossary_created_at_idx ON glossary(created_at);
